import timefrom typing import Optional, Iteratorfrom google import genaifrom google.genai import typesfrom config import (    GEMINI_API_KEYS,    GEMINI_MODELS,    AI_TEMPERATURE,    AI_MAX_OUTPUT_TOKENS,    API_KEY_FAILOVER_DELAY_SECONDS,    MODEL_RETRY_COUNT,)# ============================================================# MafiyaAI AI Engine# ============================================================if not GEMINI_API_KEYS:    raise RuntimeError(        "No Gemini API key is configured."    )# ============================================================# Gemini Clients# ============================================================CLIENTS = []for api_key in GEMINI_API_KEYS:    try:        client = genai.Client(            api_key=api_key        )        CLIENTS.append(client)    except Exception:        continueif not CLIENTS:    raise RuntimeError(        "No usable Gemini API client could be created."    )# ============================================================# Model List# ============================================================MODELS = [    str(model_name).strip()    for model_name in GEMINI_MODELS    if model_name    and str(model_name).strip()]if not MODELS:    raise RuntimeError(        "No Gemini models are configured."    )# ============================================================# Generation Configuration# ============================================================GENERATION_CONFIG = types.GenerateContentConfig(    temperature=AI_TEMPERATURE,    max_output_tokens=AI_MAX_OUTPUT_TOKENS,)# ============================================================# Validate Prompt# ============================================================def _prepare_prompt(    message: str,    conversation_context: Optional[str] = None,) -> str:    if message is None:        raise ValueError(            "Message cannot be None."        )    message = str(message).strip()    if not message:        raise ValueError(            "Message cannot be empty."        )    # AnswerBuilder provides the complete prompt.    if conversation_context:        prompt = str(            conversation_context        ).strip()    else:        prompt = message    if not prompt:        raise ValueError(            "Prompt cannot be empty."        )    return prompt# ============================================================# Extract Response Text# ============================================================def extract_response_text(    response) -> str:    if response is None:        return ""    # --------------------------------------------------------    # 1. Standard Gemini .text    # --------------------------------------------------------    try:        text = getattr(            response,            "text",            None        )        if text:            text = str(                text            ).strip()            if text:                return text    except Exception:        pass    # --------------------------------------------------------    # 2. Gemini candidates -> content -> parts -> text    # --------------------------------------------------------    try:        candidates = getattr(            response,            "candidates",            None        )        if candidates:            collected = []            for candidate in candidates:                content = getattr(                    candidate,                    "content",                    None                )                if not content:                    continue                parts = getattr(                    content,                    "parts",                    None                )                if not parts:                    continue                for part in parts:                    part_text = getattr(                        part,                        "text",                        None                    )                    if part_text:                        collected.append(                            str(part_text)                        )            result = "".join(                collected            ).strip()            if result:                return result    except Exception:        pass    # --------------------------------------------------------    # 3. Dictionary-style response fallback    # --------------------------------------------------------    try:        if isinstance(            response,            dict        ):            candidates = response.get(                "candidates",                []            )            collected = []            for candidate in candidates:                if not isinstance(                    candidate,                    dict                ):                    continue                content = candidate.get(                    "content",                    {}                )                if not isinstance(                    content,                    dict                ):                    continue                parts = content.get(                    "parts",                    []                )                for part in parts:                    if not isinstance(                        part,                        dict                    ):                        continue                    part_text = part.get(                        "text"                    )                    if part_text:                        collected.append(                            str(part_text)                        )            result = "".join(                collected            ).strip()            if result:                return result    except Exception:        pass    return ""# ============================================================# Generate AI Response# Non-Streaming / Normal Response# ============================================================def generate_ai_response(    message: str,    conversation_context: Optional[str] = None,) -> str:    prompt = _prepare_prompt(        message,        conversation_context    )    last_error = None    # ========================================================    # API KEY + MODEL FAILOVER    # ========================================================    for key_index, client in enumerate(        CLIENTS,        start=1    ):        for model_name in MODELS:            retry_count = max(                1,                int(MODEL_RETRY_COUNT)            )            for attempt in range(                retry_count            ):                try:                    response = (                        client.models.generate_content(                            model=model_name,                            contents=prompt,                            config=GENERATION_CONFIG,                        )                    )                    text = extract_response_text(                        response                    )                    if text:                        return text                    last_error = RuntimeError(                        f"API key {key_index} "                        f"with model {model_name} "                        "returned an empty response."                    )                except Exception as error:                    last_error = error                # ------------------------------------------------                # Retry delay                # ------------------------------------------------                if (                    attempt < retry_count - 1                    and API_KEY_FAILOVER_DELAY_SECONDS > 0                ):                    time.sleep(                        API_KEY_FAILOVER_DELAY_SECONDS                    )        # ========================================================        # Move to next API key        # ========================================================        if (            key_index < len(CLIENTS)            and API_KEY_FAILOVER_DELAY_SECONDS > 0        ):            time.sleep(                API_KEY_FAILOVER_DELAY_SECONDS            )    # ========================================================    # All Keys + Models Failed    # ========================================================    if last_error:        raise RuntimeError(            "All MafiyaAI Gemini API keys and models failed. "            f"Last error: {last_error}"        ) from last_error    raise RuntimeError(        "MafiyaAI could not generate a response."    )# ============================================================# STREAMING AI RESPONSE# ============================================================def stream_ai_response(    message: str,    conversation_context: Optional[str] = None,) -> Iterator[str]:    prompt = _prepare_prompt(        message,        conversation_context    )    last_error = None    # ========================================================    # API KEY + MODEL FAILOVER    # ========================================================    for key_index, client in enumerate(        CLIENTS,        start=1    ):        for model_name in MODELS:            retry_count = max(                1,                int(MODEL_RETRY_COUNT)            )            for attempt in range(                retry_count            ):                stream_started = False                try:                    # ------------------------------------------------                    # Gemini Streaming Request                    # ------------------------------------------------                    response_stream = (                        client.models.generate_content_stream(                            model=model_name,                            contents=prompt,                            config=GENERATION_CONFIG,                        )                    )                    # ------------------------------------------------                    # Receive chunks immediately                    # ------------------------------------------------                    for chunk in response_stream:                        chunk_text = (                            extract_response_text(                                chunk                            )                        )                        if not chunk_text:                            continue                        stream_started = True                        # ------------------------------------------------                        # Send immediately                        # ------------------------------------------------                        yield chunk_text                    # ------------------------------------------------                    # Empty stream                    # ------------------------------------------------                    if not stream_started:                        last_error = RuntimeError(                            f"API key {key_index} "                            f"with model {model_name} "                            "returned an empty streaming response."                        )                        continue                    # ------------------------------------------------                    # Successful stream                    # ------------------------------------------------                    return                except GeneratorExit:                    # User manually stopped / disconnected.                    # Do not convert this into an AI error.                    return                except Exception as error:                    last_error = error                    # If output already reached the user,                    # do not switch model and duplicate it.                    if stream_started:                        raise RuntimeError(                            "MafiyaAI streaming connection was "                            "interrupted after receiving partial output. "                            f"Last error: {error}"                        ) from error                # ----------------------------------------------------                # Retry                # ----------------------------------------------------                if (                    attempt < retry_count - 1                    and API_KEY_FAILOVER_DELAY_SECONDS > 0                ):                    time.sleep(                        API_KEY_FAILOVER_DELAY_SECONDS                    )        # ============================================================        # Move to next API key        # ============================================================        if (            key_index < len(CLIENTS)            and API_KEY_FAILOVER_DELAY_SECONDS > 0        ):            time.sleep(                API_KEY_FAILOVER_DELAY_SECONDS            )    # ========================================================    # All Keys + Models Failed    # ========================================================    if last_error:        raise RuntimeError(            "All MafiyaAI Gemini API keys and models failed "            "during streaming. "            f"Last error: {last_error}"        ) from last_error    raise RuntimeError(        "MafiyaAI could not generate a streaming response."    )# ============================================================# AI Connection Test# ============================================================def check_ai_connection() -> bool:    try:        response = generate_ai_response(            "Reply with exactly: OK"        )        return (            response.strip().upper()            == "OK"        )    except Exception:        return False# ============================================================# Get Active Models# ============================================================def get_available_models():    return list(        MODELS    )# ============================================================# AI Engine Status# ============================================================def get_ai_status():    return {        "configured": bool(            CLIENTS        ),        "api_key_count": len(            CLIENTS        ),        "models": get_available_models(),        "model_count": len(            MODELS        ),        "failover_delay_seconds":            API_KEY_FAILOVER_DELAY_SECONDS,        "retry_count":            MODEL_RETRY_COUNT,        "streaming":            True,        "message_limit":            None,        "memory_limit":            None,    }# ============================================================# Public Exports# ============================================================__all__ = [    "generate_ai_response",    "stream_ai_response",    "extract_response_text",    "check_ai_connection",    "get_available_models",    "get_ai_status",]